(() => {
'use strict';
const esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const nf=(x,d=3)=>x==null?'—':new Intl.NumberFormat('tr-TR',{minimumFractionDigits:d,maximumFractionDigits:d}).format(x);
const labels={silhouette:'Ortak silhouette',refit_ari:'Aylık yeniden kümeleme ARI',subsample_ari:'Alt örneklem ARI',seed_ari:'Tohum ARI',worst_group_refit_ari:'En zayıf grup ARI',worst_group_silhouette:'En düşük coğrafi grup ayrışması',min_cluster_size:'En az şube / küme'};
const gateLabels={complete_reference_groups:'Bütün referans grupları',complete_validation_and_repeats:'Bütün aylar ve tekrarlar',reference_converged:'Referans yakınsaması',reference_size:'Referans küme boyutu',validation_size:'Doğrulama küme boyutu',...labels};
const groupNames={UC_BUYUK_IL:'İstanbul / Ankara / İzmir',DIGER_ILLER:'Diğer iller'};
function coveragePanel(data){
 const contract=data.dea_coverage_contract;if(!contract)return '';
 const rows=data.full_coverage||[];
 return `<section class="card space-bottom"><div class="card-head"><div><h2>Tam şube kapsamı zorunlu</h2><p>Küme seçimi, ana DEA ve tanımlı girdi karşılaştırmalarının tamamını kapsar.</p></div></div><div class="card-body text-detail"><p>${contract.scenarios.map(s=>`${s.input_count} girdi / ${s.output_count} çıktı için ${s.required_n} şube`).join('; ')}. Ortak küme alt sınırı <strong>${contract.required_min_cluster_size}</strong> şubedir. Yüksek puan bu koşulu aşamaz.</p><p>Eksik atama, küçük küme veya DEA alan değişikliği varsa işlem durur. Şubeler elenerek kısmi sonuç üretilmez. Gerekli kapsamı sağlayan aday yoksa ana model seçilmez. Yeni ayda kapsam bozulursa seçim o aya bakılarak değiştirilmez; güncelleme gereği açıkça bildirilir.</p></div><div class="table-wrap"><table class="data-table"><thead><tr><th>Ay</th><th class="num">Kaynak şube</th><th class="num">Atanan şube</th><th class="num">Küme</th><th class="num">En küçük küme</th><th>Durum</th></tr></thead><tbody>${rows.length?rows.map(r=>`<tr><td>${esc(r.period)}</td><td class="num">${r.source_branches}</td><td class="num">${r.assigned_branches}</td><td class="num">${r.clusters}</td><td class="num">${r.min_cluster_size}</td><td>Tam kapsam</td></tr>`).join(''):'<tr><td colspan="6">Aktif aday yok; kapsam onaylanmadı.</td></tr>'}</tbody></table></div><div class="card-body"><a class="button secondary small" href="downloads/auto_cluster_full_coverage.json" download>Kapsam kanıtını indir</a></div></section>`;
}
function geographicPanel(data){
 const rows=data.geographic_quality;if(!rows)return '';
 const threshold=data.config.thresholds.worst_group_silhouette;
 return `<section class="card space-bottom"><div class="card-head"><div><h2>Her coğrafi grupta asgari küme ayrışması</h2><p>Banka ortalaması yüksek olsa da her grubun doğrulama dönemi ortalaması en az ${nf(threshold)} olmalıdır.</p></div></div><div class="card-body text-detail"><p>${data.decision.validation_periods.map(esc).join(', ')} dönemindeki sabit atama silhouette değerleri her grup için ayrı ortalandı. En düşük grup değeri ${nf(threshold)} altında kalan aday elenir. Bu sınır ayarlanabilir bir pilot politikasıdır; veriden bulunmuş en iyi eşik değildir.</p>${!data.decision.selected?'<p><strong>Güncel politikayla uygun ana model yok.</strong> Yeni şube ataması ve DEA için önce bu koşulları sağlayan ortak aday gerekir. Önceki hesaplar tarihsel sonuç olarak korunur; hiçbir bölge analizden çıkarılmaz.</p>':''}</div><div class="table-wrap"><table class="data-table"><thead><tr><th>Senaryo / yöntem</th><th>Coğrafi grup</th><th class="num">Grup ayrışması</th><th class="num">Alt sınır</th><th>Grup koşulu</th></tr></thead><tbody>${rows.map(r=>`<tr><td>${esc(r.case_id)}<span class="sub">${esc(data.method_names[r.method])}</span></td><td>${esc(groupNames[r.group]||r.group)}</td><td class="num">${nf(r.silhouette)}</td><td class="num">${nf(r.threshold)}</td><td>${r.passed?'Geçti':'Koşulu sağlamadı'}</td></tr>`).join('')}</tbody></table></div><div class="card-body"><a class="button secondary small" href="downloads/auto_cluster_geographic_quality.csv" download>Grup koşullarını indir</a></div></section>`;
}
window.renderClusterSelectionPage=data=>{
 if(!data)return '<section class="card"><div class="card-body">Otomatik kümeleme seçimi henüz çalıştırılmadı.</div></section>';
 const {decision:d,config:c,candidates,method_names:n,evaluation:e}=data,w=d.selected;
 const ranked=[...candidates].sort((a,b)=>Number(b.qualified)-Number(a.qualified)||(b.score??-1)-(a.score??-1)||a.candidate_id.localeCompare(b.candidate_id));
 const metricRow=(label,v,other)=>`<tr><td>${label}</td><td class="num">${nf(v)}</td><td class="num">${nf(other)}</td></tr>`;
 return `<div class="clustering-page model-selection-page"><div class="clustering-intro"><div><span class="badge ${w?'success':''}">${w?'Performansa göre ortak seçim':'Uygun model yok'}</span><h2>${w?esc(n[w.method]):'Ana model onaylanmadı'}</h2><p>${w?`${esc(w.case_id)} · %${nf(w.feature_ratio*100,0)} alan seçimi · ${w.feature_count} değişken · ${w.bank_clusters} toplam küme`:'Hiçbir aday bütün kalite ve boyut koşullarını sağlamadı; ana modelle atama engellendi.'}</p></div><a class="button secondary" href="downloads/auto_cluster_package.zip" download>Seçim ve model paketini indir</a></div>${!data.matches_current_grid?'<p class="inline-note">Bu karar güncel değişken şeması veya grid ile eşleşmiyor; tarihsel sonuçtur.</p>':''}<div class="kpi-grid">${[['Uygun aday',candidates.filter(x=>x.qualified).length+' / '+candidates.filter(x=>x.applicable).length,'Uygulanabilir senaryolar içinde'],['Ortak seçim puanı',nf(w?.score),'Doğruluk yüzdesi değildir'],['Seçim dönemi',d.validation_periods.join(' / '),'Bu ayların ölçüleri puana girer'],['Ayrı dönem kontrolü',e.periods.join(' / '),'Önceden incelenmiş tarihsel veri']].map(([label,value,detail])=>`<div class="kpi"><div class="kpi-head">${label}</div><div class="kpi-value">${esc(value)}</div><small>${detail}</small></div>`).join('')}</div>${coveragePanel(data)}${geographicPanel(data)}<section class="card space-bottom"><div class="card-head"><div><h2>Seçim nasıl yapılıyor?</h2><p>Yöntem, alan oranı ve küme sayısı birlikte seçilir. Üç gösterge ve iki coğrafi grup aynı yöntem ve senaryoyu kullanır.</p></div></div><div class="card-body text-detail"><ol><li>Uygulanabilirlik, tam kayıt, yakınsama ve küme boyutu kontrolleri uygulanır.</li><li>Kalite ve kararlılık eşiklerini geçen adaylar ortak puanla sıralanır.</li><li>Mevcut aday uygunsa en az ${nf(c.minimum_gain)} puan artışı olmadan değiştirilmez. Uygun aday yoksa seçim yapılmaz.</li></ol><p>${Object.entries(c.weights).map(([key,value])=>`%${nf(value*100,0)} ${esc(labels[key])}`).join(' + ')}. Her bileşen [0,1] aralığında kullanılır; sabit atama ARI puana katılmaz. Gruplar referans şube sayılarıyla, aylar eşit ağırlıkla ortalanır.</p><p>Referans ${esc(d.reference_period)}. Seçim ${d.validation_periods.map(esc).join(', ')}; ayrı kontrol ${e.periods.map(esc).join(', ')}. Sonraki dönem sonuçları seçimi geriye dönük değiştirmez. Bu aylar daha önce incelendi; dokunulmamış test değildir.</p><p>Silhouette bütün adaylarda aynı ${nf(data.manifest.common_evaluation_feature_count,0)} alanlı Gower uzaklığıyla ölçüldü; bu ölçü Gower geometrisini avantajlı kılabilir. Eşikler pilot politika tercihleridir. Gerçek veri ve müşteri profili incelemesi gerekir.</p></div></section><section class="card space-bottom"><div class="card-head"><div><h2>Adayların ortak sıralaması</h2><p>Uygun adaylar önce gösterilir. Yüksek puan tek başına eleme koşullarını aşamaz.</p></div><a class="button secondary small" href="downloads/auto_cluster_scores.csv" download>Aday puanlarını indir</a></div><div class="table-wrap"><table class="data-table"><thead><tr><th>Aday</th><th class="num">Alan / küme</th><th class="num">Puan</th><th class="num">Silhouette</th><th class="num">Yeniden kümeleme ARI</th><th class="num">Alt örneklem ARI</th><th class="num">Tohum ARI</th><th>Karar</th></tr></thead><tbody>${ranked.map(r=>`<tr><td>${esc(n[r.method])}<span class="sub mono">${esc(r.case_id)}</span>${r.candidate_id===w?.candidate_id?'<span class="badge success">Ana model</span>':''}</td><td class="num">${r.feature_count} / ${r.bank_clusters}</td><td class="num">${nf(r.score)}</td>${['silhouette','refit_ari','subsample_ari','seed_ari'].map(k=>`<td class="num">${nf(r.metrics[k])}</td>`).join('')}<td>${r.qualified?'Uygun':r.applicable?'Elendi':'Uygulanamaz'}<span class="sub">${r.reasons.map(x=>esc(gateLabels[x]||x)).join('; ')}</span></td></tr>`).join('')}</tbody></table></div></section>${w?`<div class="group-panels"><section class="card space-bottom"><div class="card-head"><div><h2>Seçilen adayın eleme koşulları</h2><p>Bu koşullar yalnızca referans ve seçim dönemini kullanır.</p></div></div><div class="table-wrap"><table class="data-table"><thead><tr><th>Koşul</th><th class="num">Ölçülen</th><th class="num">Alt sınır</th><th>Sonuç</th></tr></thead><tbody>${w.gates.map(g=>`<tr><td>${esc(gateLabels[g.name]||g.name)}</td><td class="num">${nf(g.actual)}</td><td class="num">${nf(g.threshold)}</td><td>${g.passed?'Geçti':'Elendi'}</td></tr>`).join('')}</tbody></table></div></section><section class="card space-bottom"><div class="card-head"><div><h2>Seçim ve sonraki dönem kontrolü</h2><p>Sonraki dönem bu kararın puanını veya sırasını değiştirmez.</p></div></div><div class="table-wrap"><table class="data-table"><thead><tr><th>Ölçü</th><th class="num">Seçim dönemi</th><th class="num">${e.periods.map(esc).join(' / ')}</th></tr></thead><tbody>${metricRow('Ortak silhouette',w.metrics.silhouette,e.metrics.silhouette)}${metricRow('Yeniden kümeleme ARI',w.metrics.refit_ari,e.metrics.refit_ari)}${metricRow('Sabit atama ARI · puana girmez',w.metrics.frozen_ari,e.metrics.frozen_ari)}${Object.keys(w.metrics.by_group).map(g=>metricRow(esc(groupNames[g]||g)+' · yeniden kümeleme ARI',w.metrics.by_group[g].refit_ari,e.metrics.by_group?.[g]?.refit_ari)).join('')}</tbody></table></div><div class="card-body text-detail"><p>Sonraki dönemde boyut veya kalite bozulursa yeniden inceleme gerekir; mevcut karar geriye dönük yeniden seçilmez.</p><a class="button secondary small" href="#clustering">Seçilen modelin kümelerini incele</a></div></section></div>`:''}<section class="card"><div class="card-body text-detail"><p>Sentetik pilot sonucu gerçek banka başarısını göstermez. ${data.dea_available?'DEA analizi tamamlandı; hedef dağıtımı sırada.':w?'Bu seçim için DEA henüz çalıştırılmadı.':'Güncel politika altında DEA başlatılmaz; önceki hesaplar tarihsel sonuçtur.'}</p><div class="selection-links"><a class="button secondary small" href="downloads/auto_cluster_decision.json" download>Karar kaydı</a><a class="button secondary small" href="downloads/auto_cluster_gates.csv" download>Bütün koşullar</a>${w?'<a class="button secondary small" href="downloads/auto_cluster_latest.csv" download>Ana model şube atamaları</a>':'<span>Onaylı model yok; yeni şube ataması üretilmedi.</span>'}<a class="button secondary small" href="downloads/auto_cluster_methodology.md" download>Metodoloji</a></div></div></section></div>`;
};
})();
